def answer_query(image, question="man black jacket right side"):
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    if not man_patches:
        return "No man found in the image."

    man_patch = man_patches[0]
    right_side_patches = [patch for patch in man_patch.crop(0, 0, image.width, image.height).find("right side") if patch.overlaps_with(man_patch.left, man_patch.lower, man_patch.right, man_patch.upper)]
    if not right_side_patches:
        return "No right side found for the man."

    right_side_patch = right_side_patches[0]
    jacket_patches = [patch for patch in right_side_patch.crop(0, 0, image.width, image.height).find("jacket") if patch.overlaps_with(right_side_patch.left, right_side_patch.lower, right_side_patch.right, right_side_patch.upper)]
    if not jacket_patches:
        return "No jacket found on the man's right side."

    jacket_patch = jacket_patches[0]
    color_matches = jacket_patch.best_text_match(["black"], prefix="color")
    if color_matches == "black":
        return "The man has a black jacket on his right side."
    else:
        return f"The man's jacket on the right side is {color_matches}."

